// Converter o áudio Base64 fornecido pela Evolution API para binário nativo OGG
const webhook = $('Webhook').first().json;
const msg = webhook.body?.data?.message || webhook.data?.message;
const b64 = msg?.base64 || $json.audio;

if (!b64 || typeof b64 !== 'string') {
  throw new Error("Base64 do áudio não encontrado no payload da Evolution API.");
}

const cleanB64 = b64.replace(/^data:audio\/\w+;base64,/, '');
const buffer = Buffer.from(cleanB64, 'base64');

return [{
  json: {
    status: "success",
    mimeType: "audio/ogg"
  },
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, "audio.ogg", "audio/ogg")
  }
}];

// Executar em: Run Once for All Items
const inputItems = $input.all();

const out = [];

for (const it of inputItems) {
  const j = it.json ?? {};

  // 1) Tenta output.message (objeto), 2) output (string), 3) message (string)
  let text =
    (typeof j.output?.message === 'string' && j.output.message) ||
    (typeof j.output === 'string' && j.output) ||
    (typeof j.message === 'string' && j.message) ||
    '';

  // Normaliza quebras de linha e evita parágrafos vazios
  const paragraphs = text
    .replace(/\r\n/g, '\n')
    .trim()
    .split(/\n{2,}/)
    .filter(p => p.trim().length);

  // Para cada parágrafo, cria um item de saída
  paragraphs.forEach((p, idx) => {
    out.push({
      json: {
        key: `paragraph${idx + 1}`,
        paragraph: p
      }
    });
  });
}

return out;

